  DISTINCT_PHYSICAL_REFERENCE_AMBIGUITY:["Distinct physical references remain ambiguous", "不同物理参考之间仍有歧义"],
  LOCAL_GEOMETRIC_REFERENCE_ASSIGNED:["A local geometric comparison reference was assigned", "已计算局部几何比较参考"],
