  DIVIDER_GEOMETRY_DOES_NOT_VERIFY_PAINT_ATTRIBUTES:["Divider geometry does not verify paint attributes", "分隔线几何不能核验标线属性"],
  PRIOR_BOUNDARY_IS_NOT_KNOWN_PAINTED:["The prior boundary is not recorded as painted", "历史边界未记录为有标线"],
  VISIBLE_CURVE_MAY_INDICATE_PAINT_PRESENCE_NOT_OLD_PAINT_DISPLACEMENT:["The visible curve concerns possible paint presence, not old-paint displacement", "可见曲线涉及可能存在标线，不代表旧标线位移"],
  CHANGE_PROPERTY_CANNOT_BE_RESOLVED:["The property that changed remains unresolved", "发生变化的属性尚未确定"],
  PRIOR_ATTRIBUTE_DESCRIBES_PAINTED_MARKING:["The prior attribute describes a painted marking", "历史属性描述有标线"],
  LOCAL_GEOMETRIC_RELATION_DOES_NOT_CONFIRM_PHYSICAL_MAP_CHANGE:["A local geometric relation does not confirm a physical map change", "局部几何关系不能确认物理地图变化"],
  VALID_ANNOTATION_FOOTPRINTS:['Supplied annotation footprints are geometrically valid','提供的标注轮廓几何有效'],POSITIVE_RECORDED_LANE_OVERLAP:['Recorded footprints overlap mapped lane space','记录轮廓与地图车道空间有重叠'],OCCUPANCY_IS_NOT_A_ROAD_STRUCTURE_ERROR:['Occupancy does not itself imply a road-structure error','占用本身不代表道路结构错误'],VALID_OBSERVED_MARKING_GEOMETRY:['Recorded marking geometry is valid','记录的标线几何有效'],VERIFIED_MAP_CORRESPONDENCE_UNAVAILABLE:['Verified map correspondence is unavailable','没有已核验的地图对应关系'],PHYSICAL_ALIGNMENT_UNVERIFIED:['Physical alignment is unverified','物理对齐尚未核验'],DURATION_CONDITIONAL_ON_A_REAL_CHANGE:['The source marking difference remains an unverified change hypothesis','来源标线差异仍是未经核验的变化假设'],INSUFFICIENT_TEMPORALLY_SEPARATED_LOCAL_OBSERVATIONS:['Too few temporally separated local observations','时间分离的局部观测不足'],UNSTABLE_OR_UNAVAILABLE_FIXED_ANCHOR_RESIDUAL:['Fixed-position residuals are unstable or unavailable','固定位置残差不稳定或不可得'],PRIOR_EXPLICITLY_UNPAINTED_REQUIRES_INSERTION_VERIFICATION:['Prior boundary is unpainted; insertion has not been established','原边界无标线，尚未确定新增标线'],PRIOR_MARKING_SEMANTICS_UNKNOWN:['Prior marking semantics are unknown','历史标线语义未知'],REPEATED_SIGNED_LOCAL_OFFSET_FROM_REFERENCE:['Repeated local offsets share a direction from the reference','重复局部偏移相对参考线方向一致'],OBSERVED_LOCAL_MARKING_WITHIN_ENGINEERING_TOLERANCE:['Observed local marking lies within the engineering tolerance','观测到的局部标线处于工程容差内'],CONFLICTING_LOCAL_OBSERVATIONS:['Local observations disagree','局部观测之间有冲突'],
  OBSERVED_CONFLICT_NOT_SUPPORTED:['Observed conflict is not supported','观测尚不支持冲突判定'],NO_STRUCTURAL_LAYER_PREDICTION:['This event is not routed to a structural edit','本事件不路由到结构修改'],NO_STRUCTURAL_EDIT_OPERATION:['No structural edit operation is defined','没有定义结构修改操作'],EXACT_EDIT_OBJECT_UNRESOLVED:['The exact edit object is unresolved','具体修改对象未确定'],EFFECTIVE_VISIBILITY_UNVERIFIED:['Effective visibility has not been verified','有效可见性未核验'],FULL_EDIT_GEOMETRY_UNVERIFIED:['Complete replacement geometry has not been verified','完整替代几何未核验'],NO_CURRENT_POSITIVE_OBSERVATION:['No current positive observation supports an edit','没有支持修改的当前正向观测'],EXPLICIT_RECOVERY_AFTER_LAST_SUPPORT:['Explicit recovery follows the last support','最后一次支持后出现明确恢复观测'],NEW_ELEMENT_IDENTITY_UNRESOLVED:['New element identity is unresolved','新元素身份未确定'],ADDITION_NOVELTY_UNVERIFIED:['The proposed addition has not been verified as new','尚未核验该对象确为新增'],ADDITION_REFERENCES_EXISTING_EDIT_TARGET:['Addition conflicts with an existing target reference','新增操作与已有对象引用冲突'],INVALID_OR_MISSING_EDIT_GEOMETRY:['Edit geometry is missing or invalid','修改几何缺失或无效'],VERIFIED_MARKING_PROPERTY_UNAVAILABLE:['Verified marking properties are unavailable','已核验标线属性不可得'],
