 function matches(event){return(state.filter==='all'||state.filter==='insufficient'&&event.reliability.status==='insufficient_geometry'||event.map_layer.predicted_layer===state.filter)&&(!state.search||(event.event_id+' '+event.map_aliases.map(a=>a.map_element_id).join(' ')+' '+semanticName(event)+' '+humanLabel(event)+' '+layerName(event.map_layer.predicted_layer)).toLowerCase().includes(state.search));}
 function renderList(){const found=events().filter(matches);E('event-count').textContent=found.length+' / '+events().length;E('events').innerHTML=found.map(event=>`<button style="--event-color:${eventColor(event)}" class="event-row${event.event_id===state.eventId?' active':''}" data-event="${esc(event.event_id)}" aria-pressed="${event.event_id===state.eventId}"><strong>${esc(humanLabel(event))}</strong><code>${esc(event.event_id)}</code><div class="event-kind">${esc(layerName(event.map_layer.predicted_layer))}</div><small>${esc(closedWithoutUpdate(event)?t('No map update · complete','不改底图 · 已完成'):event.decision.classification_applied?t('Applied to this observation','已用于该观测'):event.map_layer.predicted_layer==='not_applicable'?t('Observed segment consistent','观测局部一致'):t('Unverified change hypothesis','未经核验的变化假设'))}</small></button>`).join('')||`<p class="empty">${t('No events match this filter.','没有符合此筛选条件的事件。')}</p>`;E('events').querySelectorAll('[data-event]').forEach(button=>button.onclick=()=>pickEvent(button.dataset.event));}
 function geometryLines(geometry){if(!geometry)return[];if(geometry.type==='GeometryCollection')return geometry.geometries.flatMap(geometryLines);if(geometry.type==='LineString')return[geometry.coordinates];if(geometry.type==='Polygon'||geometry.type==='MultiLineString')return geometry.coordinates;if(geometry.type==='MultiPolygon')return geometry.coordinates.flat();if(geometry.type==='Point')return[[geometry.coordinates]];if(geometry.type==='MultiPoint')return geometry.coordinates.map(point=>[point]);return[];}
 function drawGeometry(event){const record=stateRecord(event),lines=geometryLines(record?.geometry||event.geometry_city),points=lines.flat();E('geometry-box').hidden=!points.length;if(!points.length)return;const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),lo=[Math.min(...xs),Math.min(...ys)],hi=[Math.max(...xs),Math.max(...ys)],scale=Math.min(320/Math.max(hi[0]-lo[0],1),115/Math.max(hi[1]-lo[1],1)),center=[(lo[0]+hi[0])/2,(lo[1]+hi[1])/2],xy=p=>[180+(p[0]-center[0])*scale,75-(p[1]-center[1])*scale];const color=eventColor(event),dashed=record?record.properties.state!=='observed_active':!isConfirmedStructure(event);E('geometry').innerHTML=lines.map(line=>`<polyline points="${line.map(p=>xy(p).join(',')).join(' ')}" stroke="${color}" fill="none" stroke-width="2" stroke-dasharray="${dashed?'6 4':''}" opacity="${record&&record.properties.state!=='observed_active'?.65:1}"/>`).join('');E('geometry-box').querySelector('p').textContent=record?t('Stored last-observed state geometry, XY view. Its current extent is not verified.','状态层存储的最后观测几何，按 XY 显示；当前范围未获核验。'):t('Supplied event geometry, XY view. No replacement map geometry is inferred.','提供的事件几何，按 XY 显示；这里没有推断替代地图几何。');}
 function renderEvaluationNote(event){let note;if(state.dataset==='argoverse'){const diagnostic=(data.evaluation.argoverse.full_boundary_geometry?.event_diagnostics||data.evaluation.argoverse.event_diagnostics).find(row=>row.event_id===event.event_id),sides=[...new Set(event.map_aliases.map(alias=>alias.boundary_side))],side=sides.length===1?(sides[0]==='left'?t('left-boundary','左边界'):sides[0]==='right'?t('right-boundary','右边界'):t('boundary','边界')):t('boundary','边界');note=!diagnostic?.in_geometry_scope?t('Outside the unambiguous boundary-geometry evaluation scope; inspect the supplied object truth separately.','不在无歧义边界几何评估范围内；对象真值需单独查看。'):diagnostic.geometry_changed_truth===false&&event.reliability.status==='supported_conflict'?t(`Predicted ${side} geometry is unchanged in truth: a geometric false positive. This evaluation concerns that boundary geometry only; a structural layer label does not validate the claimed edit.`,`预测的${side}几何在真值中未变化，因此是几何误报。本项评估只针对该边界几何；归为结构层不能证明该修改主张正确。`):diagnostic.geometry_changed_truth===false?t('The supplied boundary truth has no geometry change.','提供的边界真值没有几何变化。'):t('The supplied boundary truth has a geometry change. Matching this identity does not establish that the predicted geometry is correct.','提供的边界真值有几何变化；命中这一身份不代表预测几何正确。');const local=data.evaluation.argoverse.full_boundary_geometry?.local_geometry_checks?.find(row=>row.event_id===event.event_id);if(local){const valid=local.aliases.filter(alias=>alias.evaluable);if(valid.length)note+=' '+t('Same-anchor absolute errors: ','同一固定位置的绝对误差：')+valid.map(alias=>number(alias.median_offset_absolute_error_m,3)+' m').join(' / ')+t('; reference tolerance ','；比较容差 ')+number(data.method.reliability.residual_tolerance_m)+' m.';}E('selected-evaluation').textContent=t('EVALUATION AFTER PREDICTION · ','预测后评估 · ')+note;}else{note=stateRecord(event)?t('The state record is supported by supplied occupancy annotations. Independent structure/state classification accuracy is unavailable.','状态记录由提供的占用标注支持；独立的结构／状态分类准确率不可得。'):event.reliability.status==='supported_conflict'?t('The computed local discrepancy has observation support. It does not confirm disappearance, displacement or insertion of a marking; no independent structural truth label is available.','计算的局部差异有观测支持，但不能确认标线消失、移位或新增，也没有独立结构真值标签。'):t('Marking semantics identify a structural hypothesis; the observed change remains unverified. No independent layer accuracy is inferred.','标线语义指向结构假设，但观测变化尚未核验；不据此推算独立图层分类准确率。');E('selected-evaluation').textContent=t('SOURCE DIAGNOSTIC · ','来源诊断 · ')+note;}}
 function renderLifecycle(event){const record=stateRecord(event),cleared=dataset().state_event_layer.cleared_events?.find(row=>row.event_id===event.event_id),property=record?.properties||cleared;E('lifecycle').hidden=!property;if(!property)return;const names={observed_active:t('Observed at clip end','片段末帧仍观测到'),unknown:t('State unobserved at clip end','末帧状态未观测'),stale:t('Record expired','记录过期'),cleared:t('Explicit clearance observed','有明确解除观测')};E('lifecycle').innerHTML=`<h3>${t('Stored state lifecycle','已存储状态的生命周期')}</h3><dl>${rows([[t('State in this offline snapshot','此离线快照中的状态'),names[property.state]||property.state],[t('Last seen · source ns','最后观测 · 来源纳秒'),property.last_seen_timestamp_ns||'—'],[t('Snapshot time · source ns','快照时间 · 来源纳秒'),dataset().state_event_layer.as_of_timestamp_ns||'—'],[t('TTL supplied','提供的有效期'),property.ttl_s===null?t('None supplied','未提供'):property.ttl_s+' s'],[t('Expires at · source ns','到期时间 · 来源纳秒'),property.expires_at_timestamp_ns||'—'],[t('Clearance observed','观测到解除'),property.clearance_observed?t('Yes','是'):t('No','否')],[t('Last observed quality','最后观测质量'),number(property.observed_quality)],[t('Quality at clip end','片段末帧观测质量'),number(property.current_quality)]])}</dl><p>${esc(t('A state record remains classified as a state event when no new observation is available at the recorded clip end. This does not establish recovery. Automatic expiry requires an explicit TTL and only marks the record expired; no default TTL or clearance is invented.','片段末帧没有新观测时，已有记录仍属于状态事件，并不代表没有检测到该障碍，也不代表已经恢复。自动到期需要明确提供有效期，只将记录标记为过期；不会虚构默认有效期或解除。'))}</p><a id="state-download" class="state-download" href="../${state.dataset}_state_layer.geojson" download>${t('Download the actual state layer ↗','下载实际状态图层 ↗')}</a>`;}
 function renderFinalDecision(event){const decision=finalDecision(event),closed=closedWithoutUpdate(event),stateEvent=decision?.action==='state_event';E('final-decision').dataset.action=decision?.action||'';E('final-decision-title').textContent=stateEvent?t('State event stored','状态事件已存储'):closed?t('No map update · decision complete','不改底图 · 判定已完成'):t('Material structure update accepted','实质结构更新已采用');E('final-decision-note').textContent=stateEvent?t('The event is attached to the state layer, with its recorded geometry and lifecycle.','将事件及其记录的几何、生命周期存入状态层。'):closed?t('The supplied recording does not establish an executable material change. Keep the base map and close this candidate; no revisit or manual review is requested. This is an action decision, not a ground-truth label that the world is unchanged.','交付记录没有证明可执行的实质结构变化。保留底图并结束该候选，不要求再次采集或人工复核。这是地图处理动作，不是“现实没有变化”的真值标签。'):t('The supplied evidence identifies a material change and its edit operation. Patch execution is recorded separately below.','交付证据确定了实质变化及其修改操作；补丁执行结果在下方另行记录。');E('final-decision-reasons').innerHTML=(decision?.reason_codes||[]).map(code=>'<li>'+esc(reason(code))+'</li>').join('');}
