  E('layer-status').textContent=layerName(layer.predicted_layer);E('layer-note').textContent=layer.predicted_layer==='not_applicable'?t('The measured local geometry agrees within tolerance. This does not assess paint presence, lane use or connectivity.','测得的局部几何处于容差内；这不判断标线存在性、车道用途或连接关系。'):layer.requires_claim_split?t('Structural and operational claims are mixed. The supplied record does not resolve them into one layer.','结构与通行状态主张混合，提供的记录无法把它们确定为单一图层。'):applied?t('This semantic layer identity is applied to the supported observation. Structural editing is still checked independently.','该语义图层身份用于有观测依据的记录；结构修改仍独立检查。'):t('The semantics identify a structural subject. The final action is no map update; this candidate is complete. The raw evidence below explains the decision.','语义确定其为结构类对象；最终动作是不改底图，候选已处理完成。下方原始证据用于解释这个决定。');E('layer-values').innerHTML=rows([[t('Applied to observation','已用于观测'),applied?t('Yes','是'):t('No','否')],[t('Basis','依据'),t('Explicit semantic matching','明确语义匹配')],[t('Numeric class confidence','数值类别置信度'),layer.confidence.value===null?t('Not supplied','未提供'):number(layer.confidence.value)],[t('Uses duration to classify','用时长分类'),data.method.layer_routing.duration_used_for_classification?t('Yes','是'):t('No','否')]]);
  E('write-status').textContent=record?t('State-layer record stored','状态层记录已存储'):event.decision.base_map_write_eligible?t('Structural edit contract satisfied','满足结构修改条件'):t('Base map retained','保留基础图');E('write-note').textContent=record?t('The attached state layer holds the last observed event geometry and lifecycle. The base road structure is unchanged.','附加状态层存储最后观测的事件几何与生命周期；基础道路结构保持不变。'):t('The completed action uses only the supplied recording. Local offsets do not automatically become structural edits; no follow-up observation is requested.','最终动作仅依据交付记录。局部偏移不会自动变成结构修改，也不要求补充观测。');E('write-values').innerHTML=rows([[t('Eligible for structural edit','可进行结构修改'),gate.eligible?t('Yes','是'):t('No','否')],[t('State record stored','状态记录已存储'),record?t('Yes','是'):t('No','否')],[t('Positive observation frames','正向观测帧'),gate.positive_observation_frames],[t('Patch executed','已执行补丁'),gate.map_patch_executed?t('Yes','是'):t('No','否')]]);
  E('routing-status').textContent=layer.predicted_layer==='not_applicable'?t('NO CHANGE CLASS','无变化类别'):layer.requires_claim_split?t('MIXED CLAIMS','混合主张'):applied?t('CLASS APPLIED','已采用类别'):t('CLOSED · NO MAP UPDATE','已完成 · 不改底图');E('routing-path').innerHTML=[['base_map_structure',t('Base-map structure','基础图结构'),t('Road / lane / building geometry and topology','道路／车道／建筑的几何与拓扑')],['map_state_event',t('Attached map-state event','附加地图状态事件'),t('Occupancy, congestion and operational restrictions','占用、拥堵与通行限制')],['unresolved',t('Unresolved or mixed claim','未确定或混合主张'),t('Semantic details do not select one layer','语义细节尚不能确定单层')]].map(([id,title,note])=>`<article data-layer="${id}" class="${id===layer.predicted_layer?'active':''}"><b>${esc(title)}</b><p>${esc(note)}</p></article>`).join('');E('layer-reasons').innerHTML=layer.reasons.map(code=>`<div data-reason="${esc(code)}">${esc(reason(code))}</div>`).join('');E('matched-evidence').innerHTML=layer.matched_evidence.map(match=>`<code>${esc(match.field)} = ${esc(typeof match.value==='string'?match.value:JSON.stringify(match.value))}<br>→ ${esc(layerName(match.layer))} · ${esc(reason(match.reason))}</code>`).join('')||`<p class="note">${t('No recognized semantic match in the supplied record.','提供的记录中没有可识别的语义匹配。')}</p>`;
