 function compositeBounds(features){let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;for(const feature of features)for(const path of geometryLines(feature.geometry_city))for(const point of path){if(!Number.isFinite(point[0])||!Number.isFinite(point[1]))continue;minX=Math.min(minX,point[0]);minY=Math.min(minY,point[1]);maxX=Math.max(maxX,point[0]);maxY=Math.max(maxY,point[1]);}return Number.isFinite(minX)?[minX,minY,maxX,maxY]:null;}
